values
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',3500,$json${"question":"Which laboratory marker is most useful for assessing body iron stores?","translation":"","options":["Serum ferritin","Serum sodium","Albumin","Amylase"],"correctIndex":0,"explanation":"Ferritin broadly reflects iron stores, although it can rise during inflammation.","explanationNe":"Ferritin ले शरीरको iron store जनाउँछ, तर inflammation हुँदा पनि बढ्न सक्छ।","topic":"Iron studies"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',3501,$json${"question":"In uncomplicated iron deficiency, which pattern is most typical?","translation":"","options":["Low ferritin, low serum iron, high TIBC","High ferritin, high serum iron, low TIBC","High ferritin, low TIBC, high transferrin saturation","Normal ferritin with high serum iron"],"correctIndex":0,"explanation":"Iron deficiency typically lowers ferritin and serum iron while increasing transferrin/TIBC.","explanationNe":"Iron deficiency मा ferritin र serum iron घट्छन् तथा TIBC बढ्छ।","topic":"Iron deficiency"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3502,$json${"question":"Transferrin saturation is calculated using serum iron and:","translation":"","options":["Total iron-binding capacity","Serum calcium","Serum albumin","Creatinine clearance"],"correctIndex":0,"explanation":"Transferrin saturation is serum iron divided by TIBC, multiplied by 100.","explanationNe":"Transferrin saturation = serum iron ÷ TIBC × 100 हो।","topic":"Iron studies"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',3503,$json${"question":"Which pattern is commonly seen in anaemia of chronic inflammation?","translation":"","options":["Low serum iron with low or normal TIBC and normal/high ferritin","High serum iron and low ferritin","High TIBC and very low ferritin in every case","High transferrin saturation"],"correctIndex":0,"explanation":"Inflammation increases hepcidin and ferritin while reducing circulating iron availability.","explanationNe":"Inflammation मा hepcidin र ferritin बढ्न सक्छन् र circulating iron घट्छ।","topic":"Iron studies"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',3504,$json${"question":"Which protein transports iron in plasma?","translation":"","options":["Transferrin","Ferritin","Haptoglobin","Ceruloplasmin"],"correctIndex":0,"explanation":"Transferrin binds and transports iron through the circulation.","explanationNe":"Transferrin ले रगतमा iron बाँधेर ओसार्छ।","topic":"Iron metabolism"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',3505,$json${"question":"The major storage form of iron inside cells is:","translation":"","options":["Ferritin","Haemoglobin","Transferrin","Bilirubin"],"correctIndex":0,"explanation":"Ferritin stores iron in a soluble, relatively accessible form within cells.","explanationNe":"Ferritin कोशिकाभित्र iron भण्डारण गर्ने प्रमुख protein हो।","topic":"Iron metabolism"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',3506,$json${"question":"Which analyte is most likely to be falsely increased by haemolysis?","translation":"","options":["Potassium","Sodium","Chloride","Bicarbonate"],"correctIndex":0,"explanation":"Red-cell disruption releases intracellular potassium into serum or plasma.","explanationNe":"Hemolysis हुँदा RBC भित्रको potassium नमुनामा निस्केर बढ्न सक्छ।","topic":"Specimen interference"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',3507,$json${"question":"Which hormone produced mainly by the liver regulates systemic iron balance?","translation":"","options":["Hepcidin","Insulin","Renin","Erythropoietin"],"correctIndex":0,"explanation":"Hepcidin reduces intestinal iron absorption and iron release from macrophages.","explanationNe":"Hepcidin ले intestine बाट iron absorption र macrophage बाट iron release घटाउँछ।","topic":"Iron regulation"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',3508,$json${"question":"A high ferritin concentration alone always proves iron overload.","translation":"","options":["False","True","Only in children","Only after fasting"],"correctIndex":0,"explanation":"Ferritin is an acute-phase reactant and may rise with inflammation, liver disease and other conditions.","explanationNe":"Ferritin inflammation र liver disease मा पनि बढ्न सक्छ; एक्लैले iron overload प्रमाणित गर्दैन।","topic":"Iron interpretation"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',3509,$json${"question":"Which test is commonly used to assess circulating iron-binding capacity?","translation":"","options":["TIBC","PT","ESR","HbA1c"],"correctIndex":0,"explanation":"TIBC estimates the blood's capacity to bind iron, largely reflecting transferrin.","explanationNe":"TIBC ले रगतको iron बाँध्ने क्षमता, मुख्यतः transferrin, जनाउँछ।","topic":"Iron studies"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',3510,$json${"question":"Which mineral is the principal extracellular cation?","translation":"","options":["Sodium","Potassium","Magnesium","Phosphate"],"correctIndex":0,"explanation":"Sodium is the major cation in extracellular fluid and contributes to osmolality.","explanationNe":"Sodium extracellular fluid को प्रमुख cation हो।","topic":"Electrolytes"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',3511,$json${"question":"Most calcium in blood is normally present in which form?","translation":"","options":["Protein-bound and ionized fractions","Only free ionized calcium","Only calcium bound to albumin","Only calcium bound to phosphate"],"correctIndex":0,"explanation":"Circulating calcium is distributed among ionized, protein-bound and complexed fractions.","explanationNe":"रगतको calcium ionized, protein-bound र complexed रूपमा हुन्छ।","topic":"Calcium"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',3512,$json${"question":"Which calcium fraction is biologically active?","translation":"","options":["Ionized calcium","Albumin-bound calcium","Calcium stored in bone","Calcium bound to citrate only"],"correctIndex":0,"explanation":"Ionized calcium is the physiologically active fraction.","explanationNe":"Ionized calcium नै शरीरमा सक्रिय calcium हो।","topic":"Calcium"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',3513,$json${"question":"A low albumin concentration can cause which change in total serum calcium?","translation":"","options":["Low total calcium despite potentially normal ionized calcium","High ionized calcium in every case","No effect on total calcium","A falsely high phosphate only"],"correctIndex":0,"explanation":"Albumin-bound calcium falls with albumin, while ionized calcium may remain normal.","explanationNe":"Albumin घट्दा total calcium घट्न सक्छ, तर ionized calcium सामान्य रहन सक्छ।","topic":"Calcium interpretation"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',3514,$json${"question":"Which formula is commonly used to estimate albumin-adjusted calcium in conventional units?","translation":"","options":["Measured calcium + 0.8 × (4.0 − albumin)","Measured calcium × albumin","Albumin ÷ calcium","Measured calcium − sodium"],"correctIndex":0,"explanation":"A commonly used estimate in mg/dL and g/dL is calcium + 0.8 × (4 − albumin); local units and limitations matter.","explanationNe":"mg/dL र g/dL मा प्रचलित अनुमानित formula calcium + 0.8 × (4 − albumin) हो।","topic":"Calcium calculation"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',3515,$json${"question":"Which hormone increases serum calcium partly by increasing renal calcium reabsorption?","translation":"","options":["Parathyroid hormone","Calcitonin","Insulin","Aldosterone"],"correctIndex":0,"explanation":"PTH raises serum calcium through effects on bone, kidney and vitamin D activation.","explanationNe":"PTH ले bone, kidney र vitamin D मार्फत serum calcium बढाउँछ।","topic":"Calcium regulation"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',3516,$json${"question":"Which vitamin is essential for intestinal absorption of calcium?","translation":"","options":["Vitamin D","Vitamin C","Vitamin K only","Vitamin B1"],"correctIndex":0,"explanation":"Active vitamin D promotes intestinal absorption of calcium and phosphate.","explanationNe":"सक्रिय vitamin D ले intestine बाट calcium र phosphate absorption बढाउँछ।","topic":"Calcium regulation"}$json$::jsonb,true),
