('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',3518,$json${"question":"Which hormone generally promotes renal phosphate excretion?","translation":"","options":["Parathyroid hormone","Insulin","Prolactin","Thyroxine"],"correctIndex":0,"explanation":"PTH decreases proximal tubular phosphate reabsorption, increasing urinary phosphate.","explanationNe":"PTH ले kidney मा phosphate reabsorption घटाएर पिसाबबाट उत्सर्जन बढाउँछ।","topic":"Phosphate regulation"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',3519,$json${"question":"Which electrolyte is a major component of ATP-related cellular reactions and many enzyme systems?","translation":"","options":["Magnesium","Chloride","Bicarbonate","Iodide"],"correctIndex":0,"explanation":"Magnesium is a cofactor for numerous enzymes and stabilizes ATP-dependent reactions.","explanationNe":"Magnesium धेरै enzyme र ATP-सम्बन्धी प्रतिक्रियाका लागि आवश्यक cofactor हो।","topic":"Magnesium"}$json$::jsonb,true),
