('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',3521,$json${"question":"Which trace element is a key component of thyroid hormones?","translation":"","options":["Iodine","Zinc","Copper","Selenium"],"correctIndex":0,"explanation":"Iodine is incorporated into thyroxine (T4) and triiodothyronine (T3).","explanationNe":"Iodine thyroid hormone T3 र T4 बनाउन आवश्यक हुन्छ।","topic":"Trace elements"}$json$::jsonb,true),
