('bmlt-iron-studies-calcium-phosphate-trace-elements-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',3523,$json${"question":"Copper is an essential component of which iron-related protein?","translation":"","options":["Ceruloplasmin","Albumin","Transferrin receptor only","Haptoglobin"],"correctIndex":0,"explanation":"Ceruloplasmin is a copper-containing protein with ferroxidase activity important in iron transport.","explanationNe":"Ceruloplasmin copper भएको protein हो र iron metabolism मा भूमिका खेल्छ।","topic":"Trace elements"}$json$::jsonb,true),
