('bmlt-iron-studies-calcium-phosphate-trace-elements-mock-005','BMLT','BMLT NHPC Licensing','mock','free',3604,$json${"question":"A serum sample is visibly haemolysed and potassium is unexpectedly high. What should the laboratory consider?","translation":"","options":["Haemolysis-related pseudohyperkalemia and recollection if indicated","Immediate diagnosis of renal failure from this result alone","Reporting potassium as normal","Adding saline to the sample"],"correctIndex":0,"explanation":"Haemolysis releases intracellular potassium; interpret with sample quality and clinical context.","explanationNe":"Hemolysis ले कोशिकाभित्रको potassium बाहिर निकाल्छ; नमुनाको गुणस्तर जाँच्नुपर्छ।","topic":"Interference"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mock-006','BMLT','BMLT NHPC Licensing','mock','free',3605,$json${"question":"A patient has low total calcium and low albumin. Which measurement best clarifies physiologically active calcium?","translation":"","options":["Ionized calcium","Total protein only","Serum chloride","Urine glucose"],"correctIndex":0,"explanation":"Ionized calcium directly measures the active circulating fraction.","explanationNe":"Ionized calcium ले सक्रिय calcium प्रत्यक्ष मापन गर्छ।","topic":"Calcium assessment"}$json$::jsonb,true),
