('bmlt-iron-studies-calcium-phosphate-trace-elements-mock-009','BMLT','BMLT NHPC Licensing','mock','free',3608,$json${"question":"A newborn screening programme identifies possible iodine deficiency at population level. Which analyte is commonly assessed in population studies?","translation":"","options":["Urinary iodine concentration","Serum troponin","Plasma lactate","Serum lipase"],"correctIndex":0,"explanation":"Urinary iodine is commonly used to assess recent iodine intake in populations.","explanationNe":"Population मा iodine intake मूल्याङ्कन गर्न urinary iodine प्रयोग गरिन्छ।","topic":"Iodine assessment"}$json$::jsonb,true),
