('bmlt-iron-studies-calcium-phosphate-trace-elements-mock-011','BMLT','BMLT NHPC Licensing','mock','free',3610,$json${"question":"A trace-element sample is collected in a non-certified tube. What is the main concern?","translation":"","options":["External contamination causing inaccurate results","Automatic improvement in accuracy","Only delayed clotting","Loss of all albumin"],"correctIndex":0,"explanation":"Trace metals can leach from collection devices and contaminate specimens.","explanationNe":"Collection सामग्रीबाट metal मिसिएर नतिजा गलत आउन सक्छ।","topic":"Specimen quality"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mock-012','BMLT','BMLT NHPC Licensing','mock','free',3611,$json${"question":"A patient has low calcium, low phosphate and elevated PTH. Which broad mechanism may be involved?","translation":"","options":["Secondary hyperparathyroidism, depending on clinical context","Iron overload","Acute haemolysis","Hyperthyroidism in every case"],"correctIndex":0,"explanation":"PTH rises in response to hypocalcemia; phosphate and renal/vitamin D status help interpret the pattern.","explanationNe":"Calcium कम हुँदा PTH बढ्न सक्छ; phosphate, kidney र vitamin D पनि हेर्नुपर्छ।","topic":"Hormonal regulation"}$json$::jsonb,true),
