('bmlt-iron-studies-calcium-phosphate-trace-elements-mock-014','BMLT','BMLT NHPC Licensing','mock','free',3613,$json${"question":"A laboratory receives a sample for ionized calcium. Which pre-analytical factor is especially important?","translation":"","options":["Avoid air exposure and process promptly using the correct collection system","Leave uncapped at room temperature overnight","Transfer into an unsuitable additive tube","Shake vigorously to cause haemolysis"],"correctIndex":0,"explanation":"Air exposure changes pH and can alter measured ionized calcium; timely, appropriate handling is essential.","explanationNe":"हावासँग सम्पर्कले pH बदलिन्छ र ionized calcium नतिजा प्रभावित हुन्छ; छिटो सही handling चाहिन्छ।","topic":"Pre-analytical handling"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mock-015','BMLT','BMLT NHPC Licensing','mock','free',3614,$json${"question":"A patient has low magnesium after prolonged diarrhoea. Which explanation is most likely?","translation":"","options":["Gastrointestinal magnesium loss","Increased bone iron storage","Excess iodine intake","Increased serum albumin"],"correctIndex":0,"explanation":"Diarrhoea can cause gastrointestinal loss of magnesium.","explanationNe":"लामो समय पखाला हुँदा magnesium शरीरबाट हराउन सक्छ।","topic":"Magnesium disorders"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mock-016','BMLT','BMLT NHPC Licensing','mock','free',3615,$json${"question":"A patient with suspected Wilson disease has abnormal copper studies. Which protein is commonly measured as part of assessment?","translation":"","options":["Ceruloplasmin","Ferritin only","Haptoglobin only","Transferrin saturation only"],"correctIndex":0,"explanation":"Ceruloplasmin is commonly assessed alongside copper studies, though interpretation requires clinical context.","explanationNe":"Wilson disease मूल्याङ्कनमा copper सँगै ceruloplasmin पनि जाँचिन्छ।","topic":"Copper metabolism"}$json$::jsonb,true),
('bmlt-iron-studies-calcium-phosphate-trace-elements-mock-017','BMLT','BMLT NHPC Licensing','mock','free',3616,$json${"question":"A patient taking iron supplements has a serum iron test. Why should collection timing and clinical details be documented?","translation":"","options":["Recent dose may transiently affect serum iron","Iron tablets always lower ferritin immediately","Timing changes sodium only","Supplements invalidate all blood tests"],"correctIndex":0,"explanation":"Recent oral iron can transiently influence serum iron; follow laboratory collection guidance.","explanationNe":"हालै खाएको iron tablet ले serum iron अस्थायी रूपमा बढाउन सक्छ।","topic":"Iron studies"}$json$::jsonb,true),
